const BASE = (typeof window.__CS_BASE__ === "string" ? window.__CS_BASE__ : "/cryptosniper").replace(/\/$/, "");
const fmt=(v,d=2)=>Number(v||0).toLocaleString("fa-IR",{minimumFractionDigits:d,maximumFractionDigits:d});
const dt=v=>v?new Date(v).toLocaleString("fa-IR"):"—";
const num=v=>{const n=Number(v);return Number.isFinite(n)?n:0};
const statusFa={connected:"متصل",restricted:"محدود",pending:"در انتظار",error:"خطا",disabled:"غیرفعال",open:"باز",filled:"تکمیل",partial:"بخشی",cancelled:"لغو",failed:"ناموفق",uncertain:"نامعلوم",submitting:"در حال ارسال",new:"جدید",parsed:"تحلیل‌شده",needs_review:"نیازمند بررسی",approved:"تأییدشده",rejected:"ردشده",complete:"کامل",running:"در حال اجرا",paused:"متوقف",completed:"کامل"};

function cookie(name){
  return document.cookie.split(";").map(v=>v.trim()).find(v=>v.startsWith(name+"="))?.slice(name.length+1)||"";
}
async function api(path, opts={}){
  const method=opts.method||"GET";
  if(!navigator.onLine && !["GET","HEAD"].includes(method.toUpperCase())) throw new Error("اتصال قطع است؛ درخواست ذخیره یا ارسال نشد.");
  const headers={Accept:"application/json",...(opts.headers||{})};
  let body=opts.body;
  if(body && typeof body!=="string" && !(body instanceof FormData)){
    headers["Content-Type"]="application/json"; body=JSON.stringify(body);
  }
  if(!["GET","HEAD"].includes(method.toUpperCase())) headers["X-CSRFToken"]=decodeURIComponent(cookie("csrftoken")||cookie("cryptosniper_csrftoken"));
  const res=await fetch(BASE+path,{credentials:"same-origin",...opts,method,headers,body});
  let data={}; try{data=await res.json()}catch{}
  if(res.status===401){location.href=BASE+"/auth/login/";throw new Error("authentication_required")}
  if(!res.ok){const e=new Error(data.error?.[0]||data.error||Object.values(data.errors||{})?.[0]?.[0]?.message||"خطای درخواست");e.status=res.status;e.data=data;throw e}
  return data;
}
function useHashPage(){
  const get=()=>resolvePage(location.hash,window.__CS_INITIAL_PAGE__);
  const [page,setState]=useState(get);
  useEffect(()=>{const fn=()=>setState(get());addEventListener("hashchange",fn);return()=>removeEventListener("hashchange",fn)},[]);
  const setPage=p=>{const next=resolvePage(p);location.hash="#/"+next;setState(next)};
  return [page,setPage];
}

function App(){
  const [collapsed,setCollapsed]=useState(localStorage.getItem("cs_sidebar_collapsed")==="1");
  const [page,setPage]=useHashPage();
  const [boot,setBoot]=useState(null); const [loading,setLoading]=useState(true); const [error,setError]=useState("");
  const [decimals,setDecimals]=useState(Number(localStorage.getItem("cs_decimals")||2));
  const [toast,setToast]=useState(""); const [stepUp,setStepUp]=useState(false); const [manualSeed,setManualSeed]=useState(null);
  const [resumeAction,setResumeAction]=useState(null);
  const [ticker,setTicker]=useState({usdt_usd:null,usdt_toman:null,stale:false});
  const refresh=async()=>{try{setError("");const b=await api("/api/v1/ui/bootstrap/");setBoot(b)}catch(e){setError(e.message)}finally{setLoading(false)}};
  useEffect(()=>{refresh();const t=setInterval(refresh,60000);return()=>clearInterval(t)},[]);
  useEffect(()=>{let stop=false;const load=()=>api("/api/v1/markets/header-ticker/").then(d=>{if(!stop)setTicker(d)}).catch(()=>{});load();const t=setInterval(load,15000);return()=>{stop=true;clearInterval(t)}},[]);
  const notify=m=>{setToast(m);setTimeout(()=>setToast(""),3500)};
  const toggle=()=>{const v=!collapsed;setCollapsed(v);localStorage.setItem("cs_sidebar_collapsed",v?"1":"0")};
  const updateDecimals=v=>{setDecimals(v);localStorage.setItem("cs_decimals",String(v))};
  const menu=[
    ["dashboard","نمای کلی",LayoutDashboard],["trades","معاملات",ArrowLeftRight],
    ["inbox","صندوق سیگنال",Inbox],["exchanges","صرافی‌ها",PlugZap],
    ["telegram","تلگرام و سیگنال‌ها",MessageCircle],["alerts","هشدارها",Bell],
    ["reports","گزارش‌ها",BarChart3],["operations","وضعیت سیستم",ServerCog],["settings","تنظیمات",Settings],
  ];
  const title=["manual","smart"].includes(page)?"معامله جدید":menu.find(x=>x[0]===page)?.[1]||"CryptoSniper";
  if(loading) return <FullLoading/>;
  return <div className="app">
    <aside className={"sidebar "+(collapsed?"collapsed":"")}>
      <div className="brand"><div className="logoMark"><ChartCandlestick size={21}/></div>{!collapsed&&<div><strong>CryptoSniper</strong><span>مرکز کنترل معاملات واقعی</span></div>}</div>
      <button className="collapseBtn" aria-label="تغییر عرض فهرست" onClick={toggle}>{collapsed?<ChevronLeft size={18}/>:<ChevronRight size={18}/>}</button>
      <nav aria-label="ناوبری اصلی">{menu.map(([id,label,Icon])=><button key={id} aria-current={page===id?"page":undefined} className={"navItem "+(page===id?"active":"")} onClick={()=>setPage(id)} title={label}><Icon size={19}/>{!collapsed&&<span>{label}</span>}</button>)}</nav>
      <div className="sidebarFoot"><button className="navItem" onClick={()=>setPage("settings")}><UserCircle2 size={19}/>{!collapsed&&<span>{boot?.user?.name||"حساب کاربری"}</span>}</button><form method="post" action={BASE+"/auth/logout/"}><input type="hidden" name="csrfmiddlewaretoken" value={decodeURIComponent(cookie("csrftoken")||cookie("cryptosniper_csrftoken"))}/><button type="submit" className="navItem dangerLite" aria-label="خروج"><LogOut size={19}/>{!collapsed&&<span>خروج</span>}</button></form></div>
    </aside>
    <main className={"main "+(collapsed?"wide":"")}>
      <header className="topbar"><div><h1>{title}</h1><p>{page==="dashboard"?"همه حساب‌ها، معاملات، سیگنال‌ها و هشدارها در یک نما":"CryptoSniper · حساب واقعی"}</p></div><div className="topActions"><div className="ticker"><span>USDT / USD</span><b>{ticker.usdt_usd?fmt(ticker.usdt_usd,4):"—"}</b></div><div className="ticker"><span>USDT / تومان</span><b>{ticker.usdt_toman?Number(ticker.usdt_toman).toLocaleString("fa-IR"):"—"}</b></div><button aria-label="اعلان‌ها" className="iconBtn notification" onClick={()=>setPage("alerts")}><Bell size={19}/>{boot?.unread_notifications>0&&<span className="badge">{boot.unread_notifications>99?"99+":boot.unread_notifications}</span>}</button></div></header>
      <section className="content">
        {error&&<ErrorBox text={error}/>}
        {page==="dashboard"&&<Dashboard boot={boot} decimals={decimals} refreshBoot={refresh} setPage={setPage}/>}
        {page==="trades"&&<Trades decimals={decimals} notify={notify} setPage={setPage}/>}
        {["manual","smart"].includes(page)&&<div className="card newTradeTabs"><div className="tabs" aria-label="نوع معامله جدید"><button className={page==="manual"?"active":""} onClick={()=>setPage("manual")}>معامله دستی</button><button className={page==="smart"?"active":""} onClick={()=>setPage("smart")}>تحلیل سیگنال</button></div></div>}
        {["manual","smart"].includes(page)&&<div hidden={page!=="manual"}><Manual key={JSON.stringify(manualSeed)} boot={boot} decimals={decimals} notify={notify} requestStepUp={action=>{setResumeAction(()=>action);setStepUp(true)}} seed={manualSeed}/></div>}
        {page==="plans"&&<ManualPlans notify={notify} setPage={setPage} setManualSeed={setManualSeed}/>}
        {["manual","smart"].includes(page)&&<div hidden={page!=="smart"}><SmartPaste notify={notify} setPage={setPage} setManualSeed={setManualSeed}/></div>}
        {page==="inbox"&&<SignalInbox notify={notify} boot={boot}/>}
        {page==="exchanges"&&<Exchanges boot={boot} refreshBoot={refresh} notify={notify} requestStepUp={()=>setStepUp(true)}/>}
        {page==="wallets"&&<Wallets notify={notify}/>}
        {page==="watchlist"&&<Watchlist boot={boot} notify={notify} setPage={setPage} setManualSeed={setManualSeed}/>}
        {page==="telegram"&&<Telegram notify={notify} setPage={setPage} setManualSeed={setManualSeed} requestStepUp={()=>setStepUp(true)}/>}
        {page==="alerts"&&<Alerts notify={notify}/>}
        {page==="reports"&&<Reports decimals={decimals}/>}
        {page==="operations"&&<Operations notify={notify}/>}
        {page==="settings"&&<SettingsPage decimals={decimals} setDecimals={updateDecimals} notify={notify}/>}
      </section>
    </main>
    {toast&&<div className="toast">{toast}</div>}
    {stepUp&&<StepUpModal onClose={()=>{setStepUp(false);setResumeAction(null)}} onSuccess={async()=>{setStepUp(false);const action=resumeAction;setResumeAction(null);if(action)await action()}} notify={notify}/>}
  </div>
}
function FullLoading(){return <div className="fullLoading"><LoaderCircle className="spin"/><b>در حال بارگذاری CryptoSniper…</b></div>}
function ErrorBox({text}){return <div className="errorBox"><AlertTriangle size={18}/><span>{text}</span></div>}
function Metric({icon:Icon,label,value,hint,positive}){return <div className="metric card"><div className="metricTop"><div className="metricIcon"><Icon size={20}/></div><span>{label}</span></div><strong className={positive?"up":""}>{value}</strong><small>{hint}</small></div>}
function Status({value}){const cls=value==="connected"||value==="approved"||value==="filled"||value==="open"?"ok":value==="error"||value==="failed"||value==="rejected"?"danger":"warn";return <span className={"status "+cls}>{statusFa[value]||value||"—"}</span>}
function Empty({text="داده‌ای برای نمایش وجود ندارد."}){return <div className="emptyState">{text}</div>}

function Dashboard({boot,decimals,refreshBoot,setPage}){
  const [extra,setExtra]=useState({orders:[],external:[],signals:[],alerts:[],notifications:[],report:null});
  const [showAll,setShowAll]=useState(false);
  const load=async()=>{const [t,s,a,n,r]=await Promise.allSettled([api("/api/v1/live-orders/"),api("/api/v1/inbox/"),api("/api/v1/alerts/"),api("/api/v1/notifications/"),api("/api/v1/reports/?period=month&group=total")]);setExtra({orders:t.value?.orders||[],external:t.value?.external||[],signals:s.value?.items||[],alerts:a.value?.alerts||[],notifications:n.value?.items||[],report:r.value||null})};
  useEffect(()=>{load()},[]);
  const accounts=boot?.accounts||[];
  const usdt=accounts.reduce((sum,a)=>sum+(a.balances||[]).filter(b=>b.asset==="USDT").reduce((x,b)=>x+num(b.free),0),0);
  const total=accounts.reduce((sum,a)=>sum+(a.balances||[]).reduce((x,b)=>x+num(b.usd_value),0),0);
  const net=(extra.report?.rows||[]).reduce((s,r)=>s+num(r.net_realized),0);
  return <>
    <div className="metricGrid"><Metric icon={WalletCards} label="ارزش کل دارایی‌ها" value={`${fmt(total,decimals)} USDT`} hint="ارزش‌گذاری موجودی‌های شناخته‌شده"/><Metric icon={CircleDollarSign} label="تتر آزاد لحظه‌ای" value={`${fmt(usdt,decimals)} USDT`} hint="جمع USDT آزاد حساب‌ها"/><Metric icon={PlugZap} label="حساب‌های متصل" value={accounts.filter(a=>a.status==="connected").length} hint={`${accounts.length} حساب اصلی`}/><Metric icon={ArrowLeftRight} label="سفارش‌های واقعی" value={extra.orders.filter(x=>["open","partial","pending","submitting"].includes(x.state)).length} hint={`${extra.external.length} رکورد خارجی اخیر`}/><Metric icon={TrendingUp} label="سود خالص ماهانه" value={`${net>=0?"+":""}${fmt(net,decimals)} USDT`} hint="بر اساس گزارش تحقق‌یافته" positive={net>=0}/></div>
    <div className="grid2"><div className="card"><div className="cardHead"><div><h3>حساب‌ها و موجودی</h3><p>USDT همیشه در اولویت نمایش است</p></div><div className="row gap"><button className="softBtn" onClick={()=>setShowAll(!showAll)}>{showAll?<EyeOff size={17}/>:<Eye size={17}/>} {showAll?"فقط USDT":"تمام موجودی‌ها"}</button><button className="iconBtn" onClick={()=>{refreshBoot();load()}}><RefreshCw size={17}/></button></div></div><div className="tableScroll"><table><thead><tr><th>صرافی</th><th>USDT آزاد</th>{showAll&&<th>سایر موجودی‌ها</th>}<th>وضعیت</th><th></th></tr></thead><tbody>{accounts.map(a=>{const u=(a.balances||[]).find(b=>b.asset==="USDT");return <tr key={a.id}><td><div className="exchangeName"><span className="exchangeLogo">{a.exchange_name?.[0]||a.exchange[0]}</span><div><b>{a.exchange_name}</b><small>{a.label}</small></div></div></td><td className="usdtHighlight">{fmt(u?.free||0,decimals)} USDT</td>{showAll&&<td><div className="chips">{(a.balances||[]).filter(b=>b.asset!=="USDT"&&num(b.total)>0).slice(0,8).map(b=><span className="pill" key={b.asset}>{b.asset}: {fmt(b.total,decimals)}</span>)}</div></td>}<td><Status value={a.status}/></td><td><button className="linkBtn" onClick={()=>setPage("exchanges")}>جزئیات</button></td></tr>})}</tbody></table></div></div>
      <div className="card"><div className="cardHead"><div><h3>وضعیت حساب‌ها</h3><p>آخرین Sync و سلامت اتصال</p></div></div><div className="accountHealth">{accounts.map(a=><div className="healthRow" key={a.id}><div><b>{a.exchange_name}</b><span>{a.last_error_message||"بدون خطای ثبت‌شده"}</span></div><div><Status value={a.status}/><small>{dt(a.last_sync_at)}</small></div></div>)}</div></div></div>
    <DashboardTabs extra={extra} decimals={decimals} setPage={setPage}/>
  </>
}
function DashboardTabs({extra,decimals,setPage}){const [tab,setTab]=useState("trades");return <div className="card"><div className="tabs">{[["trades","آخرین معاملات"],["signals","آخرین سیگنال‌ها"],["alerts","آخرین هشدارها"],["notifications","اعلان‌ها"]].map(([id,l])=><button className={tab===id?"active":""} onClick={()=>setTab(id)} key={id}>{l}</button>)}</div>{tab==="trades"&&<TradesTable rows={extra.orders.slice(0,8)} decimals={decimals}/>} {tab==="signals"&&<SignalCards items={extra.signals.slice(0,6)} onMore={()=>setPage("inbox")}/>} {tab==="alerts"&&<div className="simpleList">{extra.alerts.slice(0,8).map(x=><div key={x.id}><b>{x.title}</b><span>{x.kind} · {x.threshold}</span></div>)}</div>} {tab==="notifications"&&<div className="simpleList">{extra.notifications.slice(0,8).map(x=><div key={x.id}><b>{x.title}</b><span>{x.body}</span></div>)}</div>}</div>}

function Trades({decimals,notify,setPage}){
  const [data,setData]=useState({trades:[],counts:{}});
  const [view,setView]=useState("active");
  const [selected,setSelected]=useState(null);
  const [busy,setBusy]=useState(false);
  const load=async(next=view)=>{
    try{
      const d=await api(`/api/v1/trades/?view=${next}`);
      setData(d);
      if(selected&&!d.trades?.some(x=>x.key===selected.key))setSelected(null);
      if(!selected&&d.trades?.length)setSelected(d.trades[0]);
    }catch(e){notify(e.message)}
  };
  useEffect(()=>{load(view)},[view]);
  const refresh=async()=>{
    try{
      setBusy(true);
      const d=await api("/api/v1/trades/refresh/",{method:"POST",body:{}});
      setData({trades:d.trades||[],counts:{open:d.open}});
      notify("اطلاعات واقعی صرافی‌ها تازه‌سازی شد");
    }catch(e){notify(e.message)}finally{setBusy(false)}
  };
  const archive=async item=>{
    try{
      await api("/api/v1/trades/archive/",{method:"POST",body:{kind:item.kind,id:item.id,archived:!item.archived_at}});
      notify(item.archived_at?"معامله بازیابی شد":"معامله بایگانی شد");
      setSelected(null);
      load();
    }catch(e){notify(e.message)}
  };
  const rows=data.trades||[];
  return <>
    <div className="card">
      <div className="cardHead">
        <div><h3>معاملات یکپارچه</h3><p>Internal · Live · External در یک فهرست</p></div>
        <div className="row gap"><button className="primary" onClick={()=>setPage("manual")}><PlusCircle size={18}/> معامله جدید</button><div className="range">{[["active","فعال"],["archive","بایگانی"],["all","همه"]].map(([v,l])=><button key={v} className={view===v?"active":""} onClick={()=>setView(v)}>{l}</button>)}</div><button className="softBtn" disabled={busy} onClick={refresh}><RefreshCw size={17}/> تازه‌سازی واقعی</button></div>
      </div>
      <div className="tableScroll"><table><thead><tr><th>بازار</th><th>مبدأ</th><th>جهت</th><th>Entry</th><th>وضعیت</th><th>زمان</th><th></th></tr></thead><tbody>
        {rows.map(x=><tr key={x.key} onClick={()=>setSelected(x)} className={"clickRow "+(selected?.key===x.key?"selectedRow":"")}><td><b>{x.symbol||"—"}</b><small className="blockMuted">{x.exchange}</small></td><td><span className={"pill "+(x.kind==="external"?"external":"")}>{x.origin_label}</span></td><td>{x.side||"—"}</td><td>{x.entry||"—"}</td><td><Status value={x.state}/></td><td>{dt(x.updated_at)}</td><td><button className="linkBtn dangerLite" onClick={e=>{e.stopPropagation();archive(x)}}>{x.archived_at?"بازیابی":"بایگانی"}</button></td></tr>)}
      </tbody></table>{!rows.length&&<Empty/>}</div>
    </div>
    {selected&&<div className="grid2 sectionGap">
      <div className="card chartPanel"><div className="cardHead"><div><h3>{selected.symbol||selected.key}</h3><p>{selected.origin_label} · {selected.exchange}</p></div><Status value={selected.state}/></div><MarketChart marketId={selected.market_id} trade={selected}/></div>
      <div className="card"><div className="cardHead"><div><h3>جزئیات معامله</h3><p>{selected.kind==="external"?"فقط پایش؛ مدیریت بدون واگذاری صریح غیرفعال است":"مدیریت‌شده توسط CryptoSniper"}</p></div></div><div className="analysisGrid"><Info label="Entry" value={selected.entry||"—"}/><Info label="Amount" value={selected.amount||selected.position_amount||"—"}/><Info label="Stop Loss" value={selected.stop_loss||"—"}/><Info label="TP" value={(selected.tp||[]).join(" / ")||"—"}/><Info label="وضعیت" value={selected.state||"—"}/><Info label="مبدأ" value={selected.origin_label}/></div></div>
    </div>}
  </>
}

function TradesTable({rows,decimals,onSelect}){return <div className="tableScroll"><table><thead><tr><th>بازار</th><th>صرافی</th><th>جهت</th><th>قیمت</th><th>مقدار</th><th>پرشده</th><th>وضعیت</th><th>زمان</th></tr></thead><tbody>{rows.map(x=><tr key={x.id} className={onSelect?"clickRow":""} onClick={()=>onSelect?.(x)}><td><b>{(x.symbol||"").replace("/USDT","")}</b></td><td>{x.exchange}</td><td>{x.side==="buy"?"خرید":"فروش"}</td><td>{x.average_price||x.price?fmt(x.average_price||x.price,decimals):"—"}</td><td>{fmt(x.amount,decimals)}</td><td>{fmt(x.filled_amount,decimals)}</td><td><Status value={x.state}/></td><td>{dt(x.updated_at||x.created_at)}</td></tr>)}</tbody></table>{!rows.length&&<Empty/>}</div>}
function DetailDrawer({item,onClose}){return <div className="drawerMask" onClick={onClose}><div className="drawer" onClick={e=>e.stopPropagation()}><div className="cardHead"><h3>جزئیات</h3><button className="iconBtn" onClick={onClose}><X size={18}/></button></div><pre className="jsonBox">{JSON.stringify(item,null,2)}</pre></div></div>}

function Manual({boot,decimals,notify,requestStepUp,seed}){
  const accounts=(boot?.accounts||[]).filter(a=>["connected","restricted"].includes(a.status)&&a.permissions?.can_read);
  const [accountId,setAccountId]=useState(String(seed?.account_id||accounts[0]?.id||""));
  const [market,setMarket]=useState(null), [markets,setMarkets]=useState([]);
  const [search,setSearch]=useState(""), [next,setNext]=useState(null), [total,setTotal]=useState(0);
  const [pickerOpen,setPickerOpen]=useState(false), [marketBusy,setMarketBusy]=useState(false);
  const [side,setSide]=useState(seed?.side||"long"), [entry,setEntry]=useState(String(seed?.entry||seed?.entry_price||""));
  const [tp1,setTp1]=useState(String(seed?.tp1||seed?.targets?.[0]?.price||""));
  const [tp2,setTp2]=useState(String(seed?.tp2||seed?.targets?.[1]?.price||""));
  const [tp3,setTp3]=useState(String(seed?.tp3||seed?.targets?.[2]?.price||""));
  const [sl,setSl]=useState(String(seed?.stop_loss||"")), [capital,setCapital]=useState(String(seed?.capital||""));
  const [risk,setRisk]=useState("1"), [leverage,setLeverage]=useState("1");
  const [quote,setQuote]=useState(null), [fixloss,setFixloss]=useState(null), [riskError,setRiskError]=useState("");
  const [formError,setFormError]=useState(""), [busy,setBusy]=useState(false), [uncertain,setUncertain]=useState(false);
  const [confirmed,setConfirmed]=useState(false), [trailingSL,setTrailingSL]=useState(true), [trailing,setTrailing]=useState(true);
  const [trigger,setTrigger]=useState("tp1"), [distance,setDistance]=useState("1");
  const selectionVersion=useRef(0), request=useRef(null), submitting=useRef(false), touched=useRef({});
  const account=accounts.find(a=>String(a.id)===accountId);
  useEffect(()=>{
    let active=true;
    api("/api/v1/me/trading-preferences/").then(d=>{
      if(!active)return;const p=d.trading_preferences;
      if(!seed?.capital&&!touched.current.capital)setCapital(String(Math.floor(num(p.default_order_amount))));
      if(!touched.current.trailing){setTrailingSL(seed?.trailing_sl??p.trailing_sl_enabled);setTrailing(seed?.percentage_trailing??p.trailing_tp_enabled);setTrigger(seed?.trailing_trigger||p.trailing_trigger||"tp1");setDistance(String(Math.floor(num(seed?.trailing_distance||p.trailing_distance_percent||1))));}
    }).catch(e=>setFormError(e.message));return()=>{active=false};
  },[]);
  useEffect(()=>{
    const version=++selectionVersion.current;setMarkets([]);setNext(null);setTotal(0);
    if(!accountId)return;
    const controller=new AbortController();
    const timer=setTimeout(()=>{
      setMarketBusy(true);
      api(`/api/v1/exchange-accounts/${accountId}/markets/?q=${encodeURIComponent(search)}`,{signal:controller.signal}).then(d=>{
        if(version!==selectionVersion.current)return;setMarkets(d.markets||[]);setNext(d.next_offset);setTotal(d.total);
      }).catch(e=>{if(e.name!=="AbortError"&&version===selectionVersion.current)setFormError(e.message)}).finally(()=>{if(version===selectionVersion.current)setMarketBusy(false)});
    },search?180:0);
    return()=>{clearTimeout(timer);controller.abort()};
  },[accountId,search]);
  useEffect(()=>{
    if(!seed?.market_id||String(seed.account_id||accountId)!==accountId)return;
    let active=true;api(`/api/v1/exchange-accounts/${accountId}/markets/?market_id=${seed.market_id}`).then(d=>{if(active)setMarket(d.markets?.[0]||null)}).catch(e=>setFormError(e.message));return()=>{active=false};
  },[accountId]);
  const loadMore=async()=>{
    if(next===null||marketBusy)return;const version=selectionVersion.current;setMarketBusy(true);
    try{const d=await api(`/api/v1/exchange-accounts/${accountId}/markets/?offset=${next}&q=${encodeURIComponent(search)}`);if(version===selectionVersion.current){setMarkets(v=>[...v,...d.markets]);setNext(d.next_offset)}}catch(e){setFormError(e.message)}finally{if(version===selectionVersion.current)setMarketBusy(false)}
  };
  const clearLevels=()=>{setEntry("");setTp1("");setTp2("");setTp3("");setSl("")};
  const choose=m=>{if(market?.id!==m.id)clearLevels();setMarket(m);setQuote(null);setFixloss(null);setConfirmed(false);setSearch("");setPickerOpen(false);setLeverage("1");if(m.market_type==="spot")setSide("long")};
  const changeAccount=value=>{clearLevels();setAccountId(value);setMarket(null);setMarkets([]);setSearch("");setQuote(null);setFixloss(null);setRiskError("");setConfirmed(false);setPickerOpen(true);setLeverage("1");};
  useEffect(()=>{
    setQuote(null);if(!market)return;let active=true;
    const load=()=>api(`/api/v1/markets/quotes/?market=${market.id}`).then(d=>{if(active)setQuote(d.markets?.[0]?.quote||null)}).catch(()=>{});
    load();const timer=setInterval(load,5000);return()=>{active=false;clearInterval(timer)};
  },[market?.id]);
  useEffect(()=>{
    setFixloss(null);setRiskError("");if(!market||!num(entry)||!num(sl)||!num(risk))return;
    let active=true;const timer=setTimeout(()=>api("/api/v1/risk/fix-loss/",{method:"POST",body:{account_id:accountId,market_id:market.id,entry,stop:sl,risk_percent:risk,leverage,side}}).then(d=>{if(active)setFixloss(d)}).catch(e=>{if(active)setRiskError(e.message)}),250);
    return()=>{active=false;clearTimeout(timer)};
  },[accountId,market?.id,entry,sl,risk,leverage,side]);
  useEffect(()=>setConfirmed(false),[accountId,market?.id,entry,tp1,tp2,tp3,sl,capital,leverage,trailingSL,trailing,trigger,distance]);
  const percent=value=>num(entry)&&num(value)?((num(value)-num(entry))/num(entry)*100)*(side==="short"?-1:1):null;
  const target=(label,value,setValue)=>{const pct=percent(value);return <div className="field"><label>{label}</label><div className="inputSuffix"><input aria-label={label} value={value} onChange={e=>setValue(e.target.value)} inputMode="decimal"/><span>USDT</span></div>{pct!==null&&<small className={(pct>=0?"up":"down")+" targetPercent"}>{pct>=0?"+":""}{fmt(pct,2)}٪</small>}</div>};
  const payload=()=>({account:accountId,market:market?.id,source:"manual",side,entry_price:entry,tp1,tp2:tp2||null,tp3:tp3||null,stop_loss:sl,capital,leverage:market?.market_type==="spot"?"1":leverage,trailing_sl:trailingSL,percentage_trailing:trailing,trailing_trigger:trigger,trailing_distance:distance,origin_signal:seed?.signal_id||seed?.origin_signal||null,confirmed});
  const perform=async operation=>{
    if(submitting.current)return;submitting.current=true;setBusy(true);setFormError("");
    try{
      const d=await api("/api/v1/manual/submit/",{method:"POST",body:{...operation.payload,request_key:operation.key}});
      setUncertain(false);request.current=null;notify(`سفارش #${d.order.id} ثبت شد؛ وضعیت در معاملات نمایش داده می‌شود`);location.hash="#/trades";
    }catch(e){
      if(e.status===403&&e.data?.error==="step_up_required")requestStepUp(()=>perform(operation));
      else{setFormError(e.message);if(!e.status||e.status>=500)setUncertain(true);else request.current=null;}
    }finally{submitting.current=false;setBusy(false)}
  };
  const submit=()=>{
    if(!confirmed){setFormError("تأیید ارسال سفارش را فعال کنید.");return}
    if(!market){setFormError("بازار را انتخاب کنید.");return}
    if(market.market_type!=="spot"){setFormError("ارسال سفارش این نسخه فقط برای Spot پشتیبانی می‌شود.");return}
    if(!request.current)request.current={key:crypto.randomUUID(),payload:payload()};perform(request.current);
  };
  return <div className="manualLayout"><div className="card tradeForm">
    <div className="cardHead"><div><h3>تعریف معامله واقعی</h3><p>بازار حساب انتخابی و مدیریت ریسک</p></div><span className="liveBadge"><span/> LIVE</span></div>
    {formError&&<ErrorBox text={formError}/>}
    <fieldset className="tradeFields" disabled={busy||uncertain}>
      <div className="formGrid">
        <div className="field"><label>حساب صرافی</label><select aria-label="حساب صرافی" value={accountId} onChange={e=>changeAccount(e.target.value)}>{accounts.map(a=><option key={a.id} value={a.id}>{a.exchange_name} · {a.label}</option>)}</select></div>
        <div className="field marketPicker"><label>بازار</label><button type="button" aria-label="بازار" aria-expanded={pickerOpen} className="marketSelected" onClick={()=>setPickerOpen(v=>!v)}>{market?market.base+(market.market_type==="margin"?` x${num(market.max_leverage)}`:""):"انتخاب بازار"}<Search size={15}/></button>
          {pickerOpen&&<div className="marketDropdown"><input autoFocus aria-label="جستجوی بازار" placeholder="جستجوی ارز…" value={search} onChange={e=>setSearch(e.target.value)}/><div className="marketOptions" role="listbox" aria-label="بازارهای حساب">{markets.map(m=><button type="button" role="option" aria-selected={market?.id===m.id} aria-label={m.base+(m.market_type==="margin"?` x${num(m.max_leverage)}`:"")} key={m.id} onClick={()=>choose(m)}><b>{m.base}</b><span>{m.market_type==="margin"?`x${num(m.max_leverage)}`:""}{m.favorite&&<Star size={13}/>}</span></button>)}{!marketBusy&&!markets.length&&<Empty text="بازاری پیدا نشد"/>}</div><small>{total} بازار</small>{next!==null&&<button type="button" className="softBtn" disabled={marketBusy} onClick={loadMore}>نمایش بیشتر</button>}{marketBusy&&<small role="status">در حال دریافت بازارها…</small>}</div>}
        </div>
        <div className="field"><label>قیمت زنده</label><div className="livePrice">{quote?.price?fmt(quote.price,num(quote.price)<10?6:2):"ناموجود"}<span>USDT</span></div></div>
        <div className="field"><label>جهت</label><div className="segmented"><button type="button" className={side==="long"?"active":""} onClick={()=>setSide("long")}>لانگ</button><button type="button" disabled={market?.market_type!=="margin"} className={side==="short"?"active danger":""} onClick={()=>setSide("short")}>شورت</button></div></div>
        <div className="field"><label>Entry</label><input aria-label="Entry" value={entry} onChange={e=>setEntry(e.target.value)} inputMode="decimal"/></div>
        <div className="field"><label>مارجین / اهرم</label><select aria-label="اهرم" disabled={market?.market_type!=="margin"} value={leverage} onChange={e=>setLeverage(e.target.value)}>{Array.from({length:Math.min(125,Math.max(1,Math.floor(num(market?.max_leverage||1))))},(_,i)=>i+1).map(x=><option key={x} value={x}>x{x}</option>)}</select></div>
        <div className="field"><label>حجم ورود</label><div className="inputSuffix"><input aria-label="حجم ورود" type="number" min="1" step="1" value={capital} onChange={e=>{touched.current.capital=true;setCapital(e.target.value)}} inputMode="numeric"/><span>USDT</span></div></div>
      </div>
      <div className="sectionTitle">اهداف و حد ضرر</div><div className="targetsGrid">{target("TP1",tp1,setTp1)}{target("TP2",tp2,setTp2)}{target("TP3",tp3,setTp3)}{target("Stop Loss",sl,setSl)}</div>
      <div className="fixBox"><div className="confirmLine"><input aria-label="Trailing SL" type="checkbox" checked={trailingSL} onChange={e=>{touched.current.trailing=true;setTrailingSL(e.target.checked)}}/><span>Trailing SL</span><small>TP1 → Entry</small></div><div className="confirmLine"><input aria-label="Trailing" type="checkbox" checked={trailing} onChange={e=>{touched.current.trailing=true;setTrailing(e.target.checked)}}/><span>Trailing</span></div><div className="formGrid"><div className="field"><label>شروع Trailing</label><select aria-label="شروع Trailing" value={trigger} onChange={e=>{touched.current.trailing=true;setTrigger(e.target.value)}}>{[1,2,3].map(n=><option key={n} value={"tp"+n}>{"TP"+n}</option>)}</select></div><div className="field"><label>فاصله Trailing (%)</label><input aria-label="فاصله Trailing" type="number" min="1" max="99" step="1" value={distance} onChange={e=>{touched.current.trailing=true;setDistance(e.target.value)}}/></div></div></div>
      <div className="fixBox"><div className="fixHead"><div><ShieldCheck size={20}/><b>Fix Loss</b></div></div><div className="formGrid"><div className="field"><label>ریسک مجاز</label><div className="inputSuffix"><input aria-label="ریسک مجاز" value={risk} onChange={e=>setRisk(e.target.value)} inputMode="decimal"/><span>٪</span></div></div><div className="suggestion"><span>حجم پیشنهادی</span><strong data-fixloss-suggestion>{fixloss?`${fmt(fixloss.suggested_capital??fixloss.suggested_notional,0)} USDT`:"—"}</strong>{fixloss&&<button type="button" className="softBtn" onClick={()=>{touched.current.capital=true;setCapital(fixloss.suggested_capital??String(Math.floor(num(fixloss.suggested_notional))))}}>استفاده از پیشنهاد</button>}</div></div>{fixloss&&<div className="riskDetails"><span>تتر آزاد: {fmt(fixloss.available,2)}</span><span>ریسک: {fmt(fixloss.risk_budget,2)} USDT</span><span>فاصله SL: {fmt(fixloss.stop_distance_percent,2)}٪</span><small>پیشنهاد بر مبنای فاصله استاپ است؛ کارمزد و لغزش می‌توانند زیان واقعی را تغییر دهند.</small>{fixloss.warnings?.map(w=><small key={w} className="down">{w}</small>)}</div>}{riskError&&<ErrorBox text={riskError}/>}</div>
      <label className="confirmLine"><input aria-label="تأیید ارسال سفارش" type="checkbox" checked={confirmed} onChange={e=>setConfirmed(e.target.checked)}/><span>مشخصات و ارسال سفارش را تأیید می‌کنم.</span></label>
    </fieldset>
    <div className="submitRow"><button type="button" className="primary large" disabled={busy||uncertain} onClick={submit}><Send size={17}/> ارسال سفارش</button>{uncertain&&<button type="button" className="secondary" disabled={busy} onClick={()=>perform(request.current)}>بررسی مجدد همان درخواست</button>}</div>
    {uncertain&&<p className="warningFoot">پاسخ درخواست روشن نیست؛ مشخصات ثابت نگه داشته شده و بررسی مجدد با همان شناسه انجام می‌شود.</p>}
  </div><div className="card chartPanel"><div className="cardHead"><div><h3>{market?.symbol||"نمودار بازار"}</h3><p>{account?.exchange_name||""}</p></div></div><MarketChart marketId={market?.id} levels={{entry,stop:sl,targets:[tp1,tp2,tp3].filter(Boolean)}}/></div></div>
}

function FavoriteEditor({notify}){
  const [accounts,setAccounts]=useState([]),[exchange,setExchange]=useState("");
  const [symbols,setSymbols]=useState([]),[search,setSearch]=useState(""),[results,setResults]=useState([]),[error,setError]=useState("");
  const dragged=useRef(null),scope=useRef(0);
  useEffect(()=>{let active=true;api("/api/v1/ui/bootstrap/").then(d=>{if(!active)return;const rows=Array.from(new Map((d.accounts||[]).map(a=>[a.exchange,a])).values());setAccounts(rows);setExchange(rows[0]?.exchange||"")});return()=>{active=false}},[]);
  useEffect(()=>{const version=++scope.current;setSymbols([]);setResults([]);if(!exchange)return;api(`/api/v1/ui/favorites/?exchange=${exchange}`).then(d=>{if(version===scope.current)setSymbols(d.symbols)}).catch(e=>setError(e.message));},[exchange]);
  useEffect(()=>{if(!exchange)return;let active=true;const a=accounts.find(a=>a.exchange===exchange);if(!a)return;const t=setTimeout(()=>api(`/api/v1/exchange-accounts/${a.id}/markets/?q=${encodeURIComponent(search)}`).then(d=>{if(active)setResults(Array.from(new Map(d.markets.map(m=>[m.base,m])).values()))}).catch(e=>setError(e.message)),180);return()=>{active=false;clearTimeout(t)}},[exchange,search,accounts]);
  const save=async next=>{const code=exchange;try{setError("");const d=await api("/api/v1/ui/favorites/",{method:"POST",body:{exchange:code,symbols:next}});if(code===exchange)setSymbols(d.symbols);notify("ارزهای منتخب ذخیره شدند")}catch(e){setError(e.message)}};
  const move=(from,to)=>{if(from===to||from===null)return;const next=[...symbols];next.splice(to,0,next.splice(from,1)[0]);save(next)};
  return <><div className="cardHead"><div><h3>ارزهای منتخب هر صرافی</h3><p>برای ترتیب، ردیف‌ها را بکشید؛ دکمه‌های جابه‌جایی نیز در دسترس‌اند.</p></div></div>{error&&<ErrorBox text={error}/>}<div className="formGrid"><div className="field"><label>صرافی</label><select aria-label="صرافی ارزهای منتخب" value={exchange} onChange={e=>{setExchange(e.target.value);setSearch("")}}>{accounts.map(a=><option key={a.exchange} value={a.exchange}>{a.exchange_name}</option>)}</select></div><div className="field"><label>جستجوی ارز</label><input aria-label="جستجوی ارز منتخب" value={search} onChange={e=>setSearch(e.target.value)}/></div></div><div className="favoriteRows">{symbols.map((symbol,i)=><div className="favoriteRow" key={symbol} draggable onDragStart={()=>{dragged.current=i}} onDragOver={e=>e.preventDefault()} onDrop={e=>{e.preventDefault();move(dragged.current,i);dragged.current=null}}><GripVertical size={17}/><b>{symbol}</b><button type="button" className="iconBtn" aria-label={`بالا ${symbol}`} disabled={i===0} onClick={()=>move(i,i-1)}><ChevronRight size={16}/></button><button type="button" className="iconBtn" aria-label={`پایین ${symbol}`} disabled={i===symbols.length-1} onClick={()=>move(i,i+1)}><ChevronLeft size={16}/></button><button type="button" className="iconBtn" aria-label={`حذف ${symbol}`} onClick={()=>save(symbols.filter(s=>s!==symbol))}><Trash2 size={16}/></button></div>)}</div><div className="favoriteResults">{results.filter(m=>!symbols.includes(m.base)).map(m=><button type="button" key={m.id} className="softBtn" onClick={()=>save([...symbols,m.base])}>＋ {m.base}</button>)}</div></>;
}

function ManualPlans({notify,setPage,setManualSeed}){const [plans,setPlans]=useState([]);const load=()=>api("/api/v1/ui/manual-plans/").then(d=>setPlans(d.plans||[])).catch(e=>notify(e.message));useEffect(()=>{load()},[]);const edit=x=>{setManualSeed({...x,plan_id:x.id});setPage("manual")};const confirmPlan=async x=>{try{await api(`/api/v1/manual/plans/${x.id}/confirm/`,{method:"POST",body:{revision:x.revision}});notify(`برنامه #${x.id} تأیید شد؛ هنوز سفارشی ارسال نشده است.`);load()}catch(e){notify(e.message)}};return <div className="card"><div className="cardHead"><div><h3>برنامه‌های معامله</h3><p>برنامه‌ها تنظیمات معامله‌اند؛ تأیید برنامه به‌تنهایی سفارش واقعی ارسال نمی‌کند.</p></div><div className="row gap"><button className="iconBtn" onClick={load}><RefreshCw size={17}/></button><button className="primary" onClick={()=>{setManualSeed(null);setPage("manual")}}><PlusCircle size={17}/> برنامه جدید</button></div></div><div className="tableScroll"><table><thead><tr><th>بازار</th><th>حساب</th><th>جهت</th><th>Entry</th><th>TP / SL</th><th>حجم</th><th>اهرم</th><th>وضعیت</th><th>عملیات</th></tr></thead><tbody>{plans.map(x=><tr key={x.id}><td><b>{(x.symbol||"").replace("/USDT","")}</b><small className="blockMuted">{x.market_type}</small></td><td>{x.exchange} · {x.account}</td><td>{x.side==="long"?"لانگ":"شورت"}</td><td>{x.entry}</td><td><span className="up">TP1 {x.tp1}</span><small className="blockMuted down">SL {x.stop_loss}</small></td><td>{fmt(x.capital,2)} USDT</td><td>x{Number(x.leverage||1).toFixed(0)}</td><td><span className="pill">{x.status==="ready"?"تأییدشده":"پیش‌نویس"}</span></td><td><div className="row gap">{x.status==="draft"&&<button className="softBtn" onClick={()=>edit(x)}>ویرایش</button>}{x.status==="draft"&&<button className="primary" onClick={()=>confirmPlan(x)}><CheckCircle2 size={15}/> تأیید</button>}</div></td></tr>)}</tbody></table>{!plans.length&&<Empty/>}</div></div>}

function MarketChart({marketId,signalId=null,trade=null,levels:manualLevels=null}){
  const [payload,setPayload]=useState(null);
  const [interval,setIntervalValue]=useState("5m");
  useEffect(()=>{
    setPayload(null);if(!marketId)return
    let stop=false;
    const load=async()=>{
      try{
        const q=new URLSearchParams({market:String(marketId),interval,bars:"140"});
        if(signalId)q.set("signal",String(signalId));
        if(trade?.kind==="paper")q.set("trade",String(trade.id));
        if(trade?.kind==="external")q.set("external",String(trade.id));
        const d=await api("/api/v1/markets/chart/?"+q.toString());
        if(!stop)setPayload(d);
      }catch{if(!stop)setPayload(null)}
    };
    load();
    const timer=setInterval(load,5000);
    return()=>{stop=true;clearInterval(timer)}
  },[marketId,signalId,trade?.kind,trade?.id,interval]);

  if(!marketId)return <div className="chartEmpty">یک بازار را انتخاب کنید.</div>;
  const candles=payload?.candles||[];
  if(!candles.length)return <div className="chartEmpty">در انتظار کندل و قیمت زنده…</div>;

  const levels=manualLevels?[{kind:"entry",label:"Entry",price:manualLevels.entry},{kind:"sl",label:"SL",price:manualLevels.stop},...(manualLevels.targets||[]).map((price,i)=>({kind:"tp"+(i+1),label:"TP"+(i+1),price}))].filter(x=>num(x.price)>0):(payload?.overlay?.levels||[]);
  const values=[
    ...candles.flatMap(c=>[num(c.low),num(c.high)]),
    ...levels.map(x=>num(x.price)).filter(Boolean)
  ].filter(Number.isFinite);
  const min=Math.min(...values),max=Math.max(...values),span=max-min||1;
  const W=1000,H=420,pad=28,plotH=H-pad*2,plotW=W-pad*2;
  const y=v=>pad+(max-num(v))/span*plotH;
  const step=plotW/Math.max(1,candles.length);
  const body=Math.max(2,Math.min(8,step*.62));
  const colors={entry:"#2f66d8",sl:"#e05260",tp1:"#17a673",tp2:"#17a673",tp3:"#17a673"};

  return <div className="candleWrap">
    <div className="chartToolbar">
      <small className="muted">{payload?.provider_label||"Live market"}</small>
      <div className="range">{["1m","5m","15m","1h","4h"].map(v=><button key={v} className={interval===v?"active":""} onClick={()=>setIntervalValue(v)}>{v}</button>)}</div>
    </div>
    <div className="realChart">
      <svg viewBox={`0 0 ${W} ${H}`} preserveAspectRatio="none" role="img" aria-label="نمودار زنده بازار">
        {[.25,.5,.75].map(r=><line key={r} x1={pad} x2={W-pad} y1={pad+plotH*r} y2={pad+plotH*r} stroke="#edf1f6" strokeWidth="1"/>)}
        {candles.map((c,i)=>{
          const x=pad+step*i+step/2,up=num(c.close)>=num(c.open),color=up?"#20a66a":"#df5656";
          const yo=y(c.open),yc=y(c.close),yh=y(c.high),yl=y(c.low);
          return <g key={i}><line x1={x} x2={x} y1={yh} y2={yl} stroke={color} strokeWidth="1.5"/><rect x={x-body/2} y={Math.min(yo,yc)} width={body} height={Math.max(1.5,Math.abs(yo-yc))} fill={color}/></g>
        })}
        {levels.map((level,i)=>{
          const yy=y(level.price),color=colors[level.kind]||"#17a673";
          return <g key={i}><line x1={pad} x2={W-pad} y1={yy} y2={yy} stroke={color} strokeWidth="1.5" strokeDasharray="7 5"/><text x={W-pad-5} y={Math.max(14,yy-6)} textAnchor="end" fill={color} fontSize="11" fontWeight="700">{level.label} {fmt(level.price,4)}</text></g>
        })}
        {(payload?.overlay?.markers||[]).map((m,i)=>{
          const times=candles.map(c=>Number(c.time));
          let ix=0,dist=Infinity;
          times.forEach((t,j)=>{const d=Math.abs(t-Number(m.time));if(d<dist){ix=j;dist=d}});
          const x=pad+step*ix+step/2;
          return <g key={"m"+i}><line x1={x} x2={x} y1={pad} y2={H-pad} stroke="#7d8aa0" strokeDasharray="3 5"/><text x={Math.min(W-70,x+6)} y={pad+15} fill="#52637b" fontSize="10">{m.label}</text></g>
        })}
      </svg>
    </div>
    <div className="chartFoot"><span>{payload?.market?.symbol||""}</span><span>{payload?.as_of?dt(payload.as_of):""}</span></div>
  </div>
}

function SmartPaste({notify,setPage,setManualSeed}){const [text,setText]=useState(()=>localStorage.getItem("cs_smart_text")||"");const [result,setResult]=useState(null);const [busy,setBusy]=useState(false);const run=async()=>{try{setBusy(true);const d=await api("/api/v1/smart-paste/",{method:"POST",body:{text}});setResult(d.signal);notify("سیگنال تحلیل شد")}catch(e){notify(e.message)}finally{setBusy(false)}};const snap=result?.structured;return <div className="grid2 equal"><div className="card"><div className="cardHead"><div><h3>Smart Paste</h3><p>متن سیگنال را بدون تغییر وارد کنید</p></div><ClipboardPaste size={20}/></div><textarea className="signalText" value={text} onChange={e=>setText(e.target.value)} placeholder="متن سیگنال…"/><div className="submitRow"><button className="secondary" onClick={()=>{setText("");localStorage.removeItem("cs_smart_text");setResult(null)}}>پاک کردن</button><button className="primary" disabled={busy||!text.trim()} onClick={run}><Sparkles size={18}/> تحلیل</button></div></div><div className="card"><div className="cardHead"><div><h3>نتیجه تحلیل</h3><p>قبل از معامله قابل بازبینی است</p></div>{result&&<Status value={result.status}/>}</div>{!result?<Empty text="هنوز سیگنالی تحلیل نشده است."/>:<><div className="analysisGrid"><Info label="جهت" value={snap?.side||"—"}/><Info label="Entry" value={snap?.entry||"—"}/><Info label="Stop" value={snap?.stop_loss||"—"}/><Info label="اعتماد" value={`${snap?.technical_confidence||0}٪`}/>{(snap?.targets||[]).map((t,i)=><Info key={i} label={`TP${i+1}`} value={t.price}/>)}</div><div className="aiNote"><Sparkles size={18}/><div><b>تحلیل ساختار</b><p>{snap?.parsed_payload?.extraction?.summary||"ساختار استخراج شد. حساب و بازار را قبل از اجرا انتخاب و تأیید کنید."}</p></div></div><button className="primary full" onClick={()=>{setManualSeed(snap);setPage("manual")}}>انتقال به معامله دستی</button></>}</div></div>}
function Info({label,value}){return <div className="infoBox"><span>{label}</span><b>{String(value??"—")}</b></div>}

function SignalInbox({notify,boot}){
  const [items,setItems]=useState([]),[selected,setSelected]=useState(null),[detail,setDetail]=useState(null);
  const [reason,setReason]=useState(""),[edit,setEdit]=useState(null),[markets,setMarkets]=useState([]);
  const [view,setView]=useState("active"),[layout,setLayout]=useState("cards");
  const load=async(next=view)=>{try{const d=await api(`/api/v1/inbox/?view=${next}`);setItems(d.items||[]);if(selected&&!d.items?.some(x=>x.id===selected)){setSelected(null);setDetail(null)}}catch(e){notify(e.message)}};
  useEffect(()=>{load(view)},[view]);
  const open=async id=>{setSelected(id);try{const d=await api(`/api/v1/inbox/${id}/`);setDetail(d.signal);const z=d.signal.structured||{};setEdit({account_id:z.account_id||"",market_id:z.market_id||"",side:z.side||"long",entry_price:z.entry||"",stop_loss:z.stop_loss||"",tp1:z.targets?.[0]?.price||"",tp2:z.targets?.[1]?.price||"",tp3:z.targets?.[2]?.price||""});if(z.account_id){const m=await api(`/api/v1/exchange-accounts/${z.account_id}/markets/`);setMarkets(m.markets||[])}}catch(e){notify(e.message)}};
  const changeAccount=async v=>{setEdit({...edit,account_id:v,market_id:""});try{const m=await api(`/api/v1/exchange-accounts/${v}/markets/`);setMarkets(m.markets||[])}catch(e){notify(e.message)}};
  const action=async act=>{if(!detail)return;try{const d=await api(`/api/v1/inbox/${detail.id}/action/`,{method:"POST",body:{revision:detail.revision,action:act,reason}});setDetail(d.signal);setReason("");load();notify(act==="approve"?"سیگنال تأیید شد":"سیگنال رد شد")}catch(e){notify(e.message)}};
  const saveEdit=async()=>{if(!detail||!edit)return;if(reason.trim().length<3){notify("دلیل ویرایش اجباری است و حداقل ۳ حرف باشد");return}try{const d=await api(`/api/v1/inbox/${detail.id}/edit/`,{method:"POST",body:{...edit,revision:detail.revision,reason}});setDetail(d.signal);setReason("");load();notify("ویرایش سیگنال ذخیره شد")}catch(e){notify(e.message)}};
  const archive=async item=>{try{await api(`/api/v1/inbox/${item.id}/archive/`,{method:"POST",body:{archived:!item.archived_at}});notify(item.archived_at?"سیگنال بازیابی شد":"سیگنال بایگانی شد");if(selected===item.id){setSelected(null);setDetail(null)}load()}catch(e){notify(e.message)}};
  const chosen=items.find(x=>x.id===selected);
  const cards=<div className="signalGrid compact">{items.map(x=><article className={"signalCard clickRow "+(selected===x.id?"active":"")} key={x.id} onClick={()=>open(x.id)}><div className="signalTop"><span className="coinIcon">{(x.symbol||"S")[0]}</span><div><b>{x.symbol||`Signal #${x.id}`}</b><span>{x.source_name||x.source_method}</span></div><Status value={x.status}/></div><div className="signalStats"><div><span>Entry</span><b>{x.entry||"—"}</b></div><div><span>Stop Loss</span><b>{x.stop_loss||"—"}</b></div></div><div className="signalSource row between"><span>{dt(x.created_at)}</span><button className="linkBtn dangerLite" onClick={e=>{e.stopPropagation();archive(x)}}>{x.archived_at?"بازیابی":"بایگانی"}</button></div></article>)}</div>;
  const table=<div className="tableScroll"><table><thead><tr><th>بازار</th><th>منبع</th><th>Entry</th><th>SL</th><th>وضعیت</th><th></th></tr></thead><tbody>{items.map(x=><tr key={x.id} onClick={()=>open(x.id)} className="clickRow"><td>{x.symbol||`#${x.id}`}</td><td>{x.source_name||x.source_method}</td><td>{x.entry||"—"}</td><td>{x.stop_loss||"—"}</td><td><Status value={x.status}/></td><td><button className="linkBtn dangerLite" onClick={e=>{e.stopPropagation();archive(x)}}>{x.archived_at?"بازیابی":"بایگانی"}</button></td></tr>)}</tbody></table></div>;
  return <>
    <div className="card"><div className="cardHead"><div><h3>صندوق سیگنال</h3><p>Smart Paste، دستی و Telegram · چارت و تحقق Entry/TP/SL</p></div><div className="row gap"><div className="range">{[["active","فعال"],["archive","بایگانی"],["all","همه"]].map(([v,l])=><button key={v} className={view===v?"active":""} onClick={()=>setView(v)}>{l}</button>)}</div><div className="range"><button className={layout==="cards"?"active":""} onClick={()=>setLayout("cards")}>کارت</button><button className={layout==="table"?"active":""} onClick={()=>setLayout("table")}>جدول</button></div><button className="iconBtn" onClick={()=>load()}><RefreshCw size={17}/></button></div></div>{layout==="cards"?cards:table}{!items.length&&<Empty/>}</div>
    {detail&&<div className="grid2 sectionGap">
      <div className="card chartPanel"><div className="cardHead"><div><h3>{chosen?.symbol||`Signal #${detail.id}`}</h3><p>{chosen?.source_name||chosen?.source_method||""}</p></div><Status value={detail.status}/></div><MarketChart marketId={chosen?.market_id||detail?.structured?.market_id} signalId={detail.id}/></div>
      <div className="card"><div className="cardHead"><div><h3>بازبینی سیگنال #{detail.id}</h3><p>Revision {detail.revision}</p></div><Status value={detail.status}/></div><pre className="rawSignal">{detail.raw?.original_text}</pre>{edit&&<div className="formGrid"><div className="field"><label>حساب صرافی</label><select value={edit.account_id} onChange={e=>changeAccount(e.target.value)}><option value="">انتخاب حساب</option>{(boot?.accounts||[]).map(a=><option key={a.id} value={a.id}>{a.exchange_name} · {a.label}</option>)}</select></div><div className="field"><label>بازار همان حساب</label><select value={edit.market_id} onChange={e=>setEdit({...edit,market_id:e.target.value})}><option value="">انتخاب بازار</option>{markets.map(m=><option key={m.id} value={m.id}>{m.symbol||m.base}</option>)}</select></div><div className="field"><label>جهت</label><select value={edit.side} onChange={e=>setEdit({...edit,side:e.target.value})}><option value="long">Long</option><option value="short">Short</option></select></div><div className="field"><label>Entry</label><input value={edit.entry_price} onChange={e=>setEdit({...edit,entry_price:e.target.value})}/></div><div className="field"><label>TP1</label><input value={edit.tp1} onChange={e=>setEdit({...edit,tp1:e.target.value})}/></div><div className="field"><label>TP2</label><input value={edit.tp2} onChange={e=>setEdit({...edit,tp2:e.target.value})}/></div><div className="field"><label>TP3</label><input value={edit.tp3} onChange={e=>setEdit({...edit,tp3:e.target.value})}/></div><div className="field"><label>Stop Loss</label><input value={edit.stop_loss} onChange={e=>setEdit({...edit,stop_loss:e.target.value})}/></div></div>}<div className="actionBox"><label>دلیل ویرایش / بازبینی</label><textarea value={reason} onChange={e=>setReason(e.target.value)} placeholder="برای ویرایش حداقل ۳ حرف"/><div className="row gap wrap"><button className="softBtn" onClick={saveEdit}><Save size={16}/> ذخیره ویرایش</button><button className="secondary" onClick={()=>action("reject")}>رد سیگنال</button><button className="primary" onClick={()=>action("approve")}>تأیید سیگنال</button></div></div></div>
    </div>}
  </>
}

function Exchanges({boot,refreshBoot,notify,requestStepUp}){const [catalog,setCatalog]=useState([]);const [selected,setSelected]=useState(null);const [diag,setDiag]=useState(null);const [showAdd,setShowAdd]=useState(false);const loadCatalog=()=>api("/api/v1/exchanges/").then(d=>setCatalog(d.exchanges||[]));useEffect(()=>{loadCatalog()},[]);const inspect=async a=>{setSelected(a);try{setDiag(await api(`/api/v1/exchange-accounts/${a.id}/diagnostics/`))}catch(e){notify(e.message)}};const sync=async a=>{try{await api(`/api/v1/exchange-accounts/${a.id}/sync/`,{method:"POST",body:{}});notify("بررسی اتصال و همگام‌سازی در صف قرار گرفت");setTimeout(()=>inspect(a),2500)}catch(e){notify(e.message)}};const revoke=async a=>{if(!confirm("اتصال و credential این حساب حذف شود؟"))return;try{await api(`/api/v1/exchange-accounts/${a.id}/revoke/`,{method:"POST",body:{confirmed:true}});notify("اتصال حذف شد");refreshBoot();setSelected(null)}catch(e){if(e.status===403)requestStepUp();else notify(e.message)}};const rotate=async a=>{if(!confirm("کلید رمزنگاری داخلی این اتصال گردش کند؟ پس از آن اتصال دوباره بررسی می‌شود."))return;try{await api(`/api/v1/exchange-accounts/${a.id}/rotate/`,{method:"POST",body:{confirmed:true}});notify("کلید رمزنگاری گردش یافت و بررسی مجدد در صف است");refreshBoot();setSelected(null);setDiag(null)}catch(e){if(e.status===403)requestStepUp();else notify(e.message)}};return <><div className="card"><div className="cardHead"><div><h3>حساب‌های صرافی</h3><p>فقط حساب‌های اصلی و واقعی متصل به CryptoSniper</p></div><button className="primary" onClick={()=>setShowAdd(true)}><PlusCircle size={18}/> افزودن اتصال</button></div><div className="tableScroll"><table><thead><tr><th>صرافی</th><th>USDT آزاد</th><th>آخرین Sync</th><th>وضعیت API</th><th>مجوز معامله</th><th>عملیات</th></tr></thead><tbody>{(boot?.accounts||[]).map(a=>{const u=a.balances?.find(b=>b.asset==="USDT");return <tr key={a.id}><td><div className="exchangeName"><span className="exchangeLogo">{a.exchange_name[0]}</span><div><b>{a.exchange_name}</b><small>{a.label}</small></div></div></td><td className="usdtHighlight">{fmt(u?.free||0,2)} USDT</td><td>{dt(a.last_sync_at)}</td><td><Status value={a.status}/></td><td>{a.trading_enabled?<span className="up">تأیید شده</span>:<span className="muted">خواندن/محدود</span>}</td><td><div className="row gap"><button className="softBtn" onClick={()=>inspect(a)}>جزئیات و لاگ</button><button className="iconBtn" title="همگام‌سازی" onClick={()=>sync(a)}><RefreshCw size={16}/></button><button className="iconBtn" title="گردش رمزنگاری داخلی" onClick={()=>rotate(a)}><KeyRound size={16}/></button><button className="iconBtn dangerBtn" onClick={()=>revoke(a)}><Trash2 size={16}/></button></div></td></tr>})}</tbody></table></div></div>{selected&&diag&&<Diagnostics account={selected} data={diag} onRotate={()=>rotate(selected)} onClose={()=>{setSelected(null);setDiag(null)}}/>}{showAdd&&<AddExchange catalog={catalog} onClose={()=>setShowAdd(false)} notify={notify} done={()=>{setShowAdd(false);refreshBoot()}}/>}</>}
function Diagnostics({account,data,onClose,onRotate}){const a=data.account;return <div className="drawerMask" onClick={onClose}><div className="drawer wideDrawer" onClick={e=>e.stopPropagation()}><div className="cardHead"><div><h3>لاگ اتصال {account.exchange_name}</h3><p>آخرین وضعیت قابل مشاهده بدون نمایش Secret</p></div><div className="row gap"><button className="softBtn" onClick={onRotate}><KeyRound size={16}/> گردش رمزنگاری</button><button className="iconBtn" onClick={onClose}><X size={18}/></button></div></div><div className="checkGrid">{Object.entries(data.checks||{}).map(([k,v])=><div className="checkItem" key={k}><span>{v===true?"✓":v===false?"✕":"?"}</span><b>{k}</b><small>{String(v)}</small></div>)}</div>{a.last_error?.code&&<div className="errorBox"><AlertTriangle size={18}/><div><b>{a.last_error.code}</b><span>{a.last_error.message}</span><small>{dt(a.last_error.at)}</small></div></div>}<div className="sectionTitle">موجودی‌ها</div><div className="tableScroll"><table><thead><tr><th>دارایی</th><th>آزاد</th><th>قفل</th><th>کل</th></tr></thead><tbody>{(a.balances||[]).map(b=><tr key={b.asset} className={b.asset==="USDT"?"usdtRow":""}><td><b>{b.asset}</b></td><td>{b.free}</td><td>{b.locked}</td><td>{b.total}</td></tr>)}</tbody></table></div></div></div>}
function AddExchange({catalog,onClose,notify,done}){const [form,setForm]=useState({exchange:catalog[0]?.id||"",label:"حساب اصلی",api_key:"",api_secret:"",passphrase:"",no_withdrawal_confirmed:false,ip_restricted_confirmed:false});useEffect(()=>{if(!form.exchange&&catalog[0])setForm(f=>({...f,exchange:catalog[0].id}))},[catalog]);const selected=catalog.find(x=>String(x.id)===String(form.exchange));const submit=async()=>{try{await api("/api/v1/exchange-connections/",{method:"POST",body:form});notify("اتصال ساخته شد و بررسی Worker شروع شد");done()}catch(e){notify(e.message)}};return <Modal title="افزودن اتصال صرافی" onClose={onClose}><div className="formGrid oneCol"><div className="field"><label>صرافی</label><select value={form.exchange} onChange={e=>setForm({...form,exchange:e.target.value})}>{catalog.map(x=><option value={x.id} key={x.id}>{x.name}</option>)}</select></div><div className="field"><label>نام اتصال</label><input value={form.label} onChange={e=>setForm({...form,label:e.target.value})}/></div><div className="field"><label>API Key</label><input value={form.api_key} onChange={e=>setForm({...form,api_key:e.target.value})}/></div><div className="field"><label>API Secret</label><input type="password" value={form.api_secret} onChange={e=>setForm({...form,api_secret:e.target.value})}/></div>{selected?.code==="weex"&&<div className="field"><label>Passphrase</label><input type="password" value={form.passphrase} onChange={e=>setForm({...form,passphrase:e.target.value})}/></div>}<label className="confirmLine"><input type="checkbox" checked={form.no_withdrawal_confirmed} onChange={e=>setForm({...form,no_withdrawal_confirmed:e.target.checked})}/><span>تأیید می‌کنم مجوز برداشت خاموش است.</span></label><label className="confirmLine"><input type="checkbox" checked={form.ip_restricted_confirmed} onChange={e=>setForm({...form,ip_restricted_confirmed:e.target.checked})}/><span>در صورت امکان، API به IP سرور محدود شده است.</span></label><Guide provider={selected?.code}/><button className="primary fullBtn" onClick={submit}>ثبت و تست اتصال</button></div></Modal>}

const guides={binance:["API Management بایننس را باز کنید.","کلید Read + Spot Trade بسازید.","Withdrawal باید خاموش باشد.","در صورت امکان IP سرور را در Restriction قرار دهید.","کلیدها را ثبت کنید و Sync واقعی را اجرا کنید."],bitunix:["API Management را باز کنید.","کلید Read + Spot/Trade بسازید.","Withdrawal باید خاموش باشد.","در صورت پشتیبانی IP Allowlist را فعال کنید.","کلیدها را ثبت کنید و Test Connection را بزنید."],lbank:["API Management حساب LBank را باز کنید.","مجوز Read و Trade را فعال کنید.","Withdrawal را خاموش کنید.","IP سرور را در Restriction قرار دهید.","اتصال را ثبت و Sync کنید."],nobitex:["API را در تنظیمات حساب فعال کنید.","Token با حداقل مجوز لازم بسازید.","برداشت را فعال نکنید.","پس از ثبت، موجودی و بازارها Sync می‌شوند."],weex:["API Key جدید بسازید.","Read و Spot Trade را فعال کنید.","Passphrase را یادداشت کنید.","Withdrawal خاموش و IP Restrict روشن باشد."],ourbit:["کلید API جدید بسازید.","Read + Spot Trade فقط.","برداشت خاموش.","کلیدها را ثبت و تست کنید."]};
function Guide({provider}){return <div className="guideMini"><b>راهنمای اتصال</b>{(guides[provider]||[]).map((x,i)=><div key={i}><span>{i+1}</span><p>{x}</p></div>)}</div>}

function Wallets({notify}){const [wallets,setWallets]=useState([]);const [provider,setProvider]=useState("metamask");const [network,setNetwork]=useState("ethereum");const [address,setAddress]=useState("");const [label,setLabel]=useState("کیف پول اصلی");const load=()=>api("/api/v1/wallets/").then(d=>setWallets(d.wallets||[])).catch(e=>notify(e.message));useEffect(()=>{load()},[]);const save=async(status="watch_only")=>{try{await api("/api/v1/wallets/",{method:"POST",body:{provider,network,address,label,status}});notify("کیف پول ثبت شد");setAddress("");load()}catch(e){notify(e.message)}};const browserConnect=async()=>{try{if(!window.ethereum)throw new Error("کیف پول مرورگر شناسایی نشد. MetaMask/Trust را در مرورگر فعال کنید.");const accounts=await window.ethereum.request({method:"eth_requestAccounts"});if(!accounts?.[0])throw new Error("آدرسی دریافت نشد");setAddress(accounts[0]);await api("/api/v1/wallets/",{method:"POST",body:{provider,network:"ethereum",address:accounts[0],label,status:"connected"}});notify("کیف پول مرورگر متصل و آدرس عمومی ثبت شد");load()}catch(e){notify(e.message)}};const del=async id=>{try{await api(`/api/v1/wallets/${id}/`,{method:"DELETE"});load()}catch(e){notify(e.message)}};return <div className="walletLayout"><div className="card"><div className="cardHead"><div><h3>کیف پول‌های غیرامانی</h3><p>بدون Seed Phrase و Private Key</p></div><ShieldCheck size={20}/></div><div className="formGrid oneCol"><div className="field"><label>نوع کیف پول</label><select value={provider} onChange={e=>setProvider(e.target.value)}><option value="metamask">MetaMask</option><option value="trust_wallet">Trust Wallet</option><option value="walletconnect">WalletConnect</option><option value="ledger">Ledger</option><option value="trezor">Trezor</option><option value="evm_address">EVM Address</option><option value="tron_address">TRON Address</option></select></div><div className="field"><label>شبکه</label><input value={network} onChange={e=>setNetwork(e.target.value)}/></div><div className="field"><label>نام</label><input value={label} onChange={e=>setLabel(e.target.value)}/></div><div className="field"><label>آدرس عمومی</label><input dir="ltr" value={address} onChange={e=>setAddress(e.target.value)} placeholder="0x… / TRON…"/></div><div className="securityNote"><ShieldCheck size={18}/><div><b>هیچ Secret کیف پول ذخیره نمی‌شود</b><span>اتصال این بخش فقط برای مشاهده/شناسایی آدرس است. تراکنش on-chain نیازمند تأیید جداگانه داخل کیف پول خواهد بود.</span></div></div><div className="row gap"><button className="secondary" onClick={()=>save("watch_only")}>ثبت فقط مشاهده</button>{["metamask","trust_wallet"].includes(provider)&&<button className="primary" onClick={browserConnect}><Link2 size={17}/> اتصال مرورگر</button>}</div></div></div><div className="card"><div className="cardHead"><div><h3>اتصال‌های ثبت‌شده</h3><p>برای مدیریت دارایی‌های چندمحلی</p></div></div><div className="walletList">{wallets.map(w=><div className="walletRow" key={w.id}><div><span className="walletIcon"><WalletCards size={18}/></span><div><b>{w.label}</b><small>{w.provider_label} · {w.network}</small><code>{w.address}</code></div></div><div><Status value={w.status==="connected"?"connected":"restricted"}/><button className="iconBtn dangerBtn" onClick={()=>del(w.id)}><Trash2 size={16}/></button></div></div>)}{!wallets.length&&<Empty/>}</div><div className="guideFooter"><AlertTriangle size={18}/><p>WalletConnect واقعی در مرورگر به Project ID ارائه‌دهنده نیاز دارد. تا زمان تنظیم آن، WalletConnect به‌صورت ثبت آدرس عمومی/فقط مشاهده استفاده می‌شود. Seed Phrase یا Private Key هرگز وارد CryptoSniper نشود.</p></div></div></div>}

function Watchlist({boot,notify,setPage,setManualSeed}){const [data,setData]=useState({watchlists:[]});const [active,setActive]=useState(null);const [q,setQ]=useState("");const [results,setResults]=useState([]);const [favorites,setFavorites]=useState(boot?.favorites||[]);const load=()=>api("/api/v1/ui/watchlists/").then(d=>{setData(d);if(!active&&d.watchlists?.[0])setActive(d.watchlists[0].id)});useEffect(()=>{load()},[]);useEffect(()=>{const t=setTimeout(()=>{if(q.trim())api(`/api/v1/markets/search/?q=${encodeURIComponent(q)}`).then(d=>setResults(d.results||[]));else setResults([])},300);return()=>clearTimeout(t)},[q]);const wl=data.watchlists.find(x=>x.id===active);const add=async m=>{try{await api("/api/v1/ui/watchlists/",{method:"POST",body:{action:"add",watchlist_id:active,market_id:m.id}});notify("بازار اضافه شد");load()}catch(e){notify(e.message)}};const remove=async item=>{await api("/api/v1/ui/watchlists/",{method:"POST",body:{action:"remove",watchlist_id:active,item_id:item.id}});load()};const saveFav=async arr=>{setFavorites(arr);try{await api("/api/v1/ui/favorites/",{method:"POST",body:{symbols:arr}})}catch(e){notify(e.message)}};const toggleFav=s=>saveFav(favorites.includes(s)?favorites.filter(x=>x!==s):[...favorites,s]);return <div className="grid2 equal"><div className="card"><div className="cardHead"><div><h3>ارزهای اولویت‌دار</h3><p>در همه فهرست‌های بازار بالاتر نمایش داده می‌شوند</p></div></div><div className="favoriteList">{favorites.map((f,i)=><div className="favoriteRow" key={f}><GripVertical size={18}/><span className="coinIcon">{f[0]}</span><b>{f}</b><span className="muted">اولویت {i+1}</span><button className="iconBtn" onClick={()=>saveFav(favorites.filter(x=>x!==f))}><X size={16}/></button></div>)}</div><div className="searchBox"><Search size={18}/><input placeholder="جست‌وجوی ارز…" value={q} onChange={e=>setQ(e.target.value)}/></div><div className="marketList">{results.sort((a,b)=>(favorites.includes(b.base_asset)?1:0)-(favorites.includes(a.base_asset)?1:0)).map(m=><div className="marketRow" key={m.id}><div><span className="coinIcon">{m.base_asset[0]}</span><b>{m.base_asset}</b>{m.market_type==="margin"&&<span className="pill">Margin</span>}</div><span>{m.exchange_name}</span><div><button className="iconBtn" onClick={()=>toggleFav(m.base_asset)}><Star size={17}/></button><button className="softBtn" onClick={()=>add(m)}>افزودن</button><button className="primary mini" onClick={()=>{setManualSeed({market_id:m.id,account_id:boot?.accounts?.find(a=>a.exchange===m.exchange)?.id});setPage("manual")}}>معامله</button></div></div>)}</div></div><div className="card"><div className="cardHead"><div><h3>دیده‌بان</h3><p>قیمت زنده بازارهای منتخب</p></div><select className="smallSelect" value={active||""} onChange={e=>setActive(Number(e.target.value))}>{data.watchlists.map(w=><option key={w.id} value={w.id}>{w.name}</option>)}</select></div><div className="marketList">{(wl?.items||[]).map(m=><div className="marketRow" key={m.id}><div><span className="coinIcon">{m.base[0]}</span><b>{m.base}</b>{num(m.max_leverage)>1&&<span className="pill">x{Number(m.max_leverage).toFixed(0)}</span>}</div><span className={m.quote?.stale?"muted":"up"}>{m.quote?.price||"—"}</span><div><button className="softBtn" onClick={()=>{setManualSeed({market_id:m.market_id,account_id:boot?.accounts?.find(a=>a.exchange===m.exchange)?.id});setPage("manual")}}>سیگنال دستی</button><button className="iconBtn dangerBtn" onClick={()=>remove(m)}><Trash2 size={16}/></button></div></div>)}{!wl?.items?.length&&<Empty/>}</div></div></div>}

function Telegram({notify,setPage,setManualSeed,requestStepUp}){const [state,setState]=useState(null);const [messages,setMessages]=useState([]);const [q,setQ]=useState("");const [channel,setChannel]=useState("");const [analytics,setAnalytics]=useState(null);const [connect,setConnect]=useState({api_id:"",api_hash:"",phone:"",code:"",password:""});const load=()=>Promise.all([api("/api/v1/telegram/state/"),api(`/api/v1/telegram/messages/?q=${encodeURIComponent(q)}${channel?`&channel=${channel}`:""}`)]).then(([st,m])=>{setState(st);setMessages(m.messages||[])}).catch(e=>notify(e.message));useEffect(()=>{load()},[]);useEffect(()=>{const t=setTimeout(()=>api(`/api/v1/telegram/messages/?q=${encodeURIComponent(q)}${channel?`&channel=${channel}`:""}`).then(d=>setMessages(d.messages||[])).catch(()=>{}),350);return()=>clearTimeout(t)},[q,channel]);const act=async body=>{try{const d=await api("/api/v1/telegram/action/",{method:"POST",body});if(d.discovered)notify(`${d.discovered.length} کانال پیدا شد`);else notify("عملیات Telegram انجام شد");load()}catch(e){if(e.status===403)requestStepUp();else notify(e.message)}};const loadAnalytics=async()=>{if(!channel)return;try{setAnalytics(await api(`/api/v1/telegram/channels/${channel}/analytics/`))}catch(e){notify(e.message)}};const toSmart=m=>{navigator.clipboard?.writeText(m.text);localStorage.setItem("cs_smart_text",m.text);setPage("smart")};const chosen=(state?.channels||[]).find(x=>String(x.id)===String(channel));return <div className="telegramLayout"><div className="card channels"><div className="cardHead"><div><h3>حساب Telegram</h3><p>{state?.account?.status||"—"}{state?.account?.phone_hint?` · ${state.account.phone_hint}`:""}</p></div><Status value={state?.account?.status==="connected"?"connected":"pending"}/></div>{state?.account?.status!=="connected"?<div className="connectBox"><input placeholder="API ID" value={connect.api_id} onChange={e=>setConnect({...connect,api_id:e.target.value})}/><input placeholder="API Hash" type="password" value={connect.api_hash} onChange={e=>setConnect({...connect,api_hash:e.target.value})}/><input placeholder="+98…" value={connect.phone} onChange={e=>setConnect({...connect,phone:e.target.value})}/><button className="primary" onClick={()=>act({action:"connect",api_id:connect.api_id,api_hash:connect.api_hash,phone:connect.phone})}>درخواست کد</button><input placeholder="کد ورود" value={connect.code} onChange={e=>setConnect({...connect,code:e.target.value})}/><input placeholder="رمز دومرحله‌ای" type="password" value={connect.password} onChange={e=>setConnect({...connect,password:e.target.value})}/><button className="secondary" onClick={()=>act({action:"code",code:connect.code,password:connect.password})}>تأیید کد</button></div>:<><div className="row gap pad12"><button className="softBtn" onClick={()=>act({action:"refresh"})}><RefreshCw size={16}/> دریافت کانال‌ها</button><button className="softBtn dangerLite" onClick={()=>confirm("اتصال Telegram قطع شود؟")&&act({action:"revoke"})}>قطع اتصال</button></div><div className="discovered">{(state?.discovered||[]).map(x=><div key={x.peer_id}><span>{x.title}</span><button className="linkBtn" onClick={()=>act({action:"channel",peer_id:x.peer_id,parse_mode:"hybrid",min_confidence:80,capital:100})}>افزودن</button></div>)}</div></>}<div className="channelList">{(state?.channels||[]).map(c=><button className={String(channel)===String(c.id)?"active":""} key={c.id} onClick={()=>{setChannel(c.id);setAnalytics(null)}}><div><b>{c.title}</b><small>{c.parse_mode} · {c.enabled?"زنده":"متوقف"} · {c.backfill?.status||"بدون آرشیو"}</small></div><span>{c.backfill?.imported||0}</span></button>)}</div></div><div className="card telegramFeed"><div className="cardHead"><div><h3>پیام‌های گذشته و آینده</h3><p>جست‌وجو با متن، هشتگ یا نماد</p></div><div className="row gap">{chosen&&<button className="softBtn" onClick={()=>act({action:"toggle",channel_id:chosen.id})}>{chosen.enabled?"توقف دریافت زنده":"فعال‌سازی زنده"}</button>}{chosen?.backfill&&["running","pending"].includes(chosen.backfill.status)?<button className="softBtn" onClick={()=>act({action:"archive_pause",job_id:chosen.backfill.id})}>توقف آرشیو</button>:channel&&<button className="softBtn" onClick={()=>act({action:"archive_start",channel_id:channel})}>دریافت از اولین پیام</button>}{channel&&<button className="softBtn" onClick={loadAnalytics}><BarChart3 size={16}/> آمار کانال</button>}<button className="iconBtn" onClick={load}><RefreshCw size={17}/></button></div></div>{analytics&&<div className="analyticsBox"><div className="row gap"><b>آمار کانال #{analytics.channel_id}</b><Status value={analytics.evaluation?.status}/></div><div className="analysisGrid">{Object.entries(analytics.metrics||{}).slice(0,12).map(([k,v])=><Info key={k} label={k} value={typeof v==="object"?JSON.stringify(v):String(v??"—")}/>)}</div>{analytics.evaluation&&<p className="muted">ارزیابی: {analytics.evaluation.evaluated}/{analytics.evaluation.total} · ردشده/صرف‌نظر: {analytics.evaluation.skipped}</p>}</div>}<div className="searchBox"><Search size={18}/><input value={q} onChange={e=>setQ(e.target.value)} placeholder="#BTC، Entry، متن پیام…"/></div><div className="messageList">{messages.map(m=><div className="messageCard" key={m.id}><div className="messageMeta"><b>{m.channel}</b><span>{dt(m.occurred_at)}</span><span className="pill">{m.kind}</span></div><pre>{m.text}</pre><div className="messageActions"><button className="softBtn" onClick={()=>navigator.clipboard?.writeText(m.text)}><Copy size={16}/> کپی</button><button className="primary" onClick={()=>toSmart(m)}><Sparkles size={16}/> ارسال به تحلیل سیگنال</button></div></div>)}{!messages.length&&<Empty/>}</div></div></div>}
function Alerts({notify}){const blank={id:null,version:1,title:"",kind:"price",threshold:"",market:"",direction:"above",repeat:false,hysteresis:"0.1",cooldown_seconds:60,enabled:true};const [items,setItems]=useState([]);const [notes,setNotes]=useState([]);const [q,setQ]=useState("");const [markets,setMarkets]=useState([]);const [form,setForm]=useState(blank);const load=()=>Promise.all([api("/api/v1/alerts/"),api("/api/v1/notifications/")]).then(([a,n])=>{setItems(a.alerts||[]);setNotes(n.items||[])}).catch(e=>notify(e.message));useEffect(()=>{load()},[]);useEffect(()=>{const t=setTimeout(()=>{if(q.trim())api(`/api/v1/markets/search/?q=${encodeURIComponent(q)}`).then(d=>setMarkets((d.results||[]).filter(x=>x.market_type==="spot")));else setMarkets([])},300);return()=>clearTimeout(t)},[q]);const save=async(next=form)=>{try{await api("/api/v1/alerts/",{method:"POST",body:{...next,market:next.market,trade:""}});notify(next.id?"هشدار ویرایش شد":"هشدار ذخیره شد");setForm(blank);setQ("");load()}catch(e){notify(e.message)}};const edit=a=>{setForm({id:a.id,version:a.version,title:a.title,kind:a.kind,threshold:a.threshold,market:String(a.market_id),direction:a.direction||"above",repeat:!!a.repeat,hysteresis:a.hysteresis||"0.1",cooldown_seconds:a.cooldown_seconds||60,enabled:a.enabled});setQ(a.market_symbol||"");setMarkets([{id:a.market_id,base_asset:(a.market_symbol||"").replace("/USDT",""),exchange_name:a.market_exchange}]);};const toggle=a=>save({id:a.id,version:a.version,title:a.title,kind:a.kind,threshold:a.threshold,market:String(a.market_id),direction:a.direction||"above",repeat:!!a.repeat,hysteresis:a.hysteresis||"0.1",cooldown_seconds:a.cooldown_seconds||60,enabled:!a.enabled});const markRead=async id=>{try{await api(`/api/v1/notifications/${id}/read/`,{method:"POST",body:{}});load()}catch(e){notify(e.message)}};return <><div className="grid2 equal"><div className="card"><div className="cardHead"><div><h3>هشدارها</h3><p>هشدار فقط اطلاع‌رسانی می‌کند و معامله را تغییر نمی‌دهد</p></div></div><div className="simpleList">{items.map(a=><div key={a.id}><div><b>{a.title}</b><span>{a.market_symbol} · {a.kind} · {a.threshold} · {a.fire_count} اعلان</span></div><div className="row gap"><Status value={a.enabled?"connected":"disabled"}/><button className="softBtn" onClick={()=>edit(a)}>ویرایش</button><button className="softBtn" onClick={()=>toggle(a)}>{a.enabled?"خاموش":"فعال"}</button></div></div>)}{!items.length&&<Empty/>}</div></div><div className="card"><div className="cardHead"><div><h3>{form.id?"ویرایش هشدار":"هشدار جدید"}</h3><p>برای بازارهای Spot متصل</p></div>{form.id&&<button className="softBtn" onClick={()=>{setForm(blank);setQ("")}}>انصراف</button>}</div><div className="formGrid oneCol"><div className="field"><label>عنوان</label><input value={form.title} onChange={e=>setForm({...form,title:e.target.value})}/></div><div className="field"><label>جست‌وجوی بازار</label><input value={q} onChange={e=>setQ(e.target.value)} placeholder="BTC"/><select value={form.market} onChange={e=>setForm({...form,market:e.target.value})}><option value="">انتخاب بازار</option>{markets.map(m=><option key={m.id} value={m.id}>{m.base_asset} · {m.exchange_name}</option>)}</select></div><div className="field"><label>نوع</label><select value={form.kind} onChange={e=>setForm({...form,kind:e.target.value})}><option value="price">رسیدن به قیمت</option><option value="rise">افزایش درصدی</option><option value="fall">کاهش درصدی</option></select></div><div className="field"><label>جهت عبور</label><select value={form.direction} onChange={e=>setForm({...form,direction:e.target.value})}><option value="above">بالاتر یا مساوی</option><option value="below">پایین‌تر یا مساوی</option></select></div><div className="field"><label>Threshold</label><input value={form.threshold} onChange={e=>setForm({...form,threshold:e.target.value})}/></div><div className="field"><label>Cooldown (ثانیه)</label><input value={form.cooldown_seconds} onChange={e=>setForm({...form,cooldown_seconds:e.target.value})}/></div><label className="confirmLine"><input type="checkbox" checked={form.repeat} onChange={e=>setForm({...form,repeat:e.target.checked})}/><span>هشدار تکرارشونده</span></label><button className="primary fullBtn" onClick={()=>save()}>{form.id?"ذخیره تغییرات":"ذخیره هشدار"}</button></div></div></div><div className="card sectionGap"><div className="cardHead"><div><h3>اعلان‌ها</h3><p>آخرین اعلان‌های داخل برنامه</p></div><button className="iconBtn" onClick={load}><RefreshCw size={17}/></button></div><div className="simpleList">{notes.map(n=><div key={n.id} className={n.read?"mutedRow":""}><div><b>{n.title}</b><span>{n.body}</span></div>{n.read?<span className="pill">خوانده‌شده</span>:<button className="softBtn" onClick={()=>markRead(n.id)}>خواندم</button>}</div>)}{!notes.length&&<Empty/>}</div></div></>}
function Reports({decimals}){const [period,setPeriod]=useState("month");const [data,setData]=useState(null);useEffect(()=>{api(`/api/v1/reports/?period=${period}&group=total`).then(setData)},[period]);const net=(data?.rows||[]).reduce((s,r)=>s+num(r.net_realized),0);return <div className="card"><div className="cardHead"><div><h3>گزارش عملکرد</h3><p>سود/زیان تحقق‌یافته و هزینه‌ها</p></div><div className="row gap"><select className="smallSelect" value={period} onChange={e=>setPeriod(e.target.value)}><option value="day">روز</option><option value="week">هفته</option><option value="month">ماه</option></select><a className="softBtn" href={BASE+`/reports/export.csv?period=${period}&group=total`}>CSV</a></div></div><div className="metricGrid reportMetrics"><Metric icon={TrendingUp} label="خالص" value={`${fmt(net,decimals)} USDT`} hint={period}/><Metric icon={ArrowLeftRight} label="معاملات" value={(data?.rows||[]).reduce((s,r)=>s+num(r.trades),0)} hint="کل"/><Metric icon={CircleDollarSign} label="کارمزد" value={fmt((data?.rows||[]).reduce((s,r)=>s+num(r.fees),0),decimals)} hint="USDT"/></div><div className="tableScroll"><table><thead><tr><th>بازه</th><th>معاملات</th><th>برد</th><th>باخت</th><th>Gross</th><th>Fee</th><th>Net</th></tr></thead><tbody>{(data?.rows||[]).map((r,i)=><tr key={i}><td>{dt(r.period_start)}</td><td>{r.trades}</td><td>{r.wins}</td><td>{r.losses}</td><td>{fmt(r.gross_realized,decimals)}</td><td>{fmt(r.fees,decimals)}</td><td className={num(r.net_realized)>=0?"up":"down"}>{fmt(r.net_realized,decimals)}</td></tr>)}</tbody></table></div></div>}

function Operations({notify}){const [data,setData]=useState(null);const [engine,setEngine]=useState(null);const [host,setHost]=useState(null);const [deploy,setDeploy]=useState(null);const load=()=>Promise.allSettled([api("/api/v1/operations/health/"),api("/api/v1/engine/readiness/"),api("/api/v1/operations/host-capabilities/"),api("/api/v1/deployment/readiness/")]).then(([a,b,c,d])=>{if(a.value)setData(a.value);if(b.value)setEngine(b.value);if(c.value)setHost(c.value);if(d.value)setDeploy(d.value)});useEffect(()=>{load();const t=setInterval(load,30000);return()=>clearInterval(t)},[]);const workers=Array.isArray(data?.workers)?data.workers:Object.entries(data?.workers||{}).map(([queue,v])=>({queue,...(typeof v==="object"?v:{value:v})}));const control=async(a,action)=>{try{await api(`/api/v1/operations/accounts/${a.id}/control/`,{method:"POST",body:{action,version:a.version,confirmed:true}});notify(action==="reconcile"?"تطبیق حساب در صف قرار گرفت":action==="pause"?"ورود جدید متوقف شد":"ورود جدید فعال شد");setTimeout(load,1200)}catch(e){notify(e.message)}};return <div className="operationsGrid"><div className="card"><div className="cardHead"><div><h3>کنترل حساب‌های واقعی</h3><p>توقف ورود جدید، تطبیق و ادامه امن</p></div><button className="iconBtn" onClick={load}><RefreshCw size={17}/></button></div><div className="simpleList">{(data?.accounts||[]).map(a=><div key={a.id}><div><b>{a.exchange} · {a.label}</b><span>Sync: {dt(a.last_sync_at)} · تطبیق: {dt(a.last_reconciled_at)}</span></div><div className="row gap"><span className={a.paused?"status warn":"status ok"}>{a.paused?"ورود متوقف":"ورود فعال"}</span><button className="softBtn" onClick={()=>control(a,"reconcile")}>تطبیق</button><button className="softBtn" onClick={()=>control(a,a.paused?"resume":"pause")}>{a.paused?"ادامه":"توقف ورود"}</button></div></div>)}{!(data?.accounts||[]).length&&<Empty/>}</div></div><div className="card"><div className="cardHead"><div><h3>Workerها</h3><p>صف‌های مستقل CryptoSniper</p></div></div><div className="simpleList">{workers.map((v,i)=><div key={v.queue||i}><div><b>{v.queue||"worker"}</b><span>آخرین حضور: {dt(v.seen_at)} · lag {v.lag_seconds??"—"}</span></div><span className={v.fresh===false?"status danger":"status ok"}>{v.fresh===false?"قدیمی":"فعال"}</span></div>)}</div></div>{(data?.unresolved_issues||[]).length>0&&<div className="card"><div className="cardHead"><div><h3>موارد نیازمند بررسی</h3><p>اختلاف‌های باز ثبت‌شده توسط موتور تطبیق</p></div></div><div className="simpleList">{data.unresolved_issues.map(x=><div key={x.id}><div><b>{x.account}</b><span>{x.code} · {x.key}</span></div><small>{dt(x.created_at)}</small></div>)}</div></div>}<div className="card"><div className="cardHead"><div><h3>آمادگی موتور</h3><p>وضعیت سرویس‌ها و قفل‌های ایمنی</p></div></div><pre className="jsonBox">{JSON.stringify(engine,null,2)}</pre></div><div className="card"><div className="cardHead"><div><h3>قابلیت‌های سرور</h3><p>توانمندی‌های Host و وابستگی‌ها</p></div></div><pre className="jsonBox">{JSON.stringify(host,null,2)}</pre></div><div className="card"><div className="cardHead"><div><h3>آمادگی استقرار</h3><p>چک نهایی اجرای Production</p></div></div><pre className="jsonBox">{JSON.stringify(deploy,null,2)}</pre></div></div>}
function SettingsPage({decimals,setDecimals,notify}){const [tab,setTab]=useState(window.__CS_INITIAL_SUBPAGE__||"profile");const [profile,setProfile]=useState(null);const [prefs,setPrefs]=useState(null);const [sources,setSources]=useState([]);const [notePrefs,setNotePrefs]=useState(null);const [security,setSecurity]=useState({sessions:[],audit:[]});const load=()=>Promise.allSettled([api("/api/v1/me/"),api("/api/v1/me/trading-preferences/"),api("/api/v1/ui/signal-sources/"),api("/api/v1/ui/notification-preferences/"),api("/api/v1/ui/security/")]).then(([a,b,c,d,e])=>{if(a.value)setProfile(a.value.profile);if(b.value)setPrefs(b.value.trading_preferences);if(c.value)setSources(c.value.sources||[]);if(d.value)setNotePrefs(d.value.preferences);if(e.value)setSecurity(e.value)});useEffect(()=>{load()},[]);const saveProfile=async()=>{try{const d=await api("/api/v1/me/",{method:"PATCH",body:{display_name:profile.display_name,email:profile.email,timezone:profile.timezone,base_currency:profile.base_currency,theme:profile.theme}});setProfile(d.profile);notify("پروفایل ذخیره شد")}catch(e){notify(e.message)}};const savePrefs=async()=>{try{const body={default_order_amount:String(Math.round(num(prefs.default_order_amount))),default_market:prefs.default_market,tp1_percent:prefs.tp_distribution?.[0]||"10",tp2_percent:prefs.tp_distribution?.[1]||"10",tp3_percent:prefs.tp_distribution?.[2]||"80",trailing_sl_enabled:!!prefs.trailing_sl_enabled,trailing_tp_enabled:!!prefs.trailing_tp_enabled,trailing_trigger:prefs.trailing_trigger||"tp1",trailing_distance_percent:String(Math.max(1,Math.round(num(prefs.trailing_distance_percent||1))))};const d=await api("/api/v1/me/trading-preferences/",{method:"PATCH",body});setPrefs(d.trading_preferences);notify("پیش‌فرض‌های معامله ذخیره شد")}catch(e){notify(e.message)}};const toggleSource=async x=>{try{const d=await api("/api/v1/ui/signal-sources/",{method:"POST",body:{id:x.id,enabled:!x.enabled}});setSources(d.sources||[])}catch(e){notify(e.message)}};const saveNotePrefs=async next=>{try{const d=await api("/api/v1/ui/notification-preferences/",{method:"PATCH",body:next});setNotePrefs(d.preferences);notify("تنظیم اعلان ذخیره شد")}catch(e){notify(e.message)}};const revokeSession=async id=>{try{const d=await api("/api/v1/ui/security/",{method:"POST",body:{action:"revoke_session",session_id:id}});setSecurity(d);notify("نشست بسته شد")}catch(e){notify(e.message)}};return <div className="settingsLayout"><div className="settingsNav card">{[["profile","پروفایل و نمایش"],["trading","پیش‌فرض معامله"],["favorites","ارزهای منتخب"],["sources","منابع سیگنال"],["notifications","اعلان‌ها"],["security","امنیت و نشست‌ها"]].map(([id,l])=><button key={id} className={tab===id?"active":""} onClick={()=>setTab(id)}>{l}</button>)}</div><div className="card">{tab==="favorites"&&<FavoriteEditor notify={notify}/>} {tab==="profile"&&<><div className="cardHead"><div><h3>پروفایل و نمایش</h3><p>رابط فارسی و تنظیمات حساب</p></div></div>{profile&&<div className="formGrid"><div className="field"><label>نام نمایشی</label><input value={profile.display_name||""} onChange={e=>setProfile({...profile,display_name:e.target.value})}/></div><div className="field"><label>ایمیل</label><input value={profile.email||""} onChange={e=>setProfile({...profile,email:e.target.value})}/></div><div className="field"><label>منطقه زمانی</label><input value={profile.timezone||""} onChange={e=>setProfile({...profile,timezone:e.target.value})}/></div><div className="field"><label>ارز پایه</label><input value={profile.base_currency||"USDT"} onChange={e=>setProfile({...profile,base_currency:e.target.value})}/></div></div>}<div className="settingRow"><div><b>تعداد اعشار نمایشی</b><span>دقت موتور داخلی حفظ می‌شود.</span></div><select value={decimals} onChange={e=>setDecimals(Number(e.target.value))}><option value="0">بدون اعشار</option><option value="1">۱ رقم</option><option value="2">۲ رقم</option><option value="4">۴ رقم</option></select></div><div className="submitRow"><button className="primary" onClick={saveProfile}><Save size={17}/> ذخیره پروفایل</button></div></>}{tab==="trading"&&prefs&&<><div className="cardHead"><div><h3>پیش‌فرض‌های معامله</h3><p>مقادیر پیش‌فرض معاملات حساب‌های واقعی</p></div></div><div className="formGrid"><div className="field"><label>مبلغ پیش‌فرض USDT</label><input value={Math.round(num(prefs.default_order_amount))} onChange={e=>setPrefs({...prefs,default_order_amount:e.target.value.replace(/\D/g,"")})}/><small>بدون اعشار</small></div><div className="field"><label>بازار پیش‌فرض</label><select value={prefs.default_market} onChange={e=>setPrefs({...prefs,default_market:e.target.value})}><option value="spot">Spot</option><option value="margin">Margin</option></select></div><div className="field"><label>تقسیم TP1/TP2/TP3</label><input value={(prefs.tp_distribution||[]).join("/")} onChange={e=>{const a=e.target.value.replace(/[^0-9/]/g,"").split("/").slice(0,3);setPrefs({...prefs,tp_distribution:a})}} placeholder="10/10/80"/><small>فقط عدد صحیح؛ پیش‌فرض 10/10/80</small></div><div className="field"><label>شروع Trailing TP</label><select value={prefs.trailing_trigger||"tp1"} onChange={e=>setPrefs({...prefs,trailing_trigger:e.target.value})}><option value="tp1">TP1</option><option value="tp2">TP2</option><option value="tp3">TP3</option></select></div><div className="field"><label>فاصله Trailing ٪</label><input inputMode="numeric" value={String(prefs.trailing_distance_percent??"1").replace(/\.0+$/,"")} onChange={e=>setPrefs({...prefs,trailing_distance_percent:e.target.value.replace(/\D/g,"")})}/><small>فقط عدد صحیح</small></div><label className="confirmLine"><input type="checkbox" checked={!!prefs.trailing_sl_enabled} onChange={e=>setPrefs({...prefs,trailing_sl_enabled:e.target.checked})}/><span>Trailing SL پیش‌فرض</span></label><label className="confirmLine"><input type="checkbox" checked={!!prefs.trailing_tp_enabled} onChange={e=>setPrefs({...prefs,trailing_tp_enabled:e.target.checked})}/><span>Trailing TP پیش‌فرض</span></label></div><div className="submitRow"><button className="primary" onClick={savePrefs}><Save size={17}/> ذخیره پیش‌فرض‌ها</button></div></>}{tab==="sources"&&<><div className="cardHead"><div><h3>منابع سیگنال</h3><p>منابع داخلی؛ Telegram از صفحه Telegram مدیریت می‌شود</p></div></div><div className="simpleList">{sources.map(x=><div key={x.id}><div><b>{x.name}</b><span>{x.method}</span></div>{x.method==="telegram"?<span className="pill">مدیریت در Telegram</span>:<button className={x.enabled?"softBtn":"primary"} onClick={()=>toggleSource(x)}>{x.enabled?"غیرفعال کردن":"فعال کردن"}</button>}</div>)}</div></>}{tab==="notifications"&&notePrefs&&<><div className="cardHead"><div><h3>تنظیم اعلان‌ها</h3><p>نحوه دریافت هشدارهای CryptoSniper</p></div></div><div className="settingRow"><div><b>اعلان داخل برنامه</b><span>نمایش در مرکز اعلان‌ها</span></div><input type="checkbox" checked={!!notePrefs.in_app} onChange={e=>saveNotePrefs({...notePrefs,in_app:e.target.checked})}/></div><div className="settingRow"><div><b>اعلان مرورگر</b><span>در صورت اجازه مرورگر</span></div><input type="checkbox" checked={!!notePrefs.browser} onChange={e=>saveNotePrefs({...notePrefs,browser:e.target.checked})}/></div></>}{tab==="security"&&<><div className="cardHead"><div><h3>امنیت و نشست‌ها</h3><p>نشست‌های فعال و Audit اخیر</p></div></div><div className="sectionTitle">نشست‌ها</div><div className="simpleList">{(security.sessions||[]).map(x=><div key={x.id}><div><b>{x.current?"این دستگاه":(x.label||`Session #${x.id}`)}</b><span>آخرین فعالیت: {dt(x.last_seen_at)} · انقضا: {dt(x.expires_at)}</span></div>{x.current?<span className="status ok">جاری</span>:<button className="softBtn" disabled={!x.valid} onClick={()=>revokeSession(x.id)}>بستن نشست</button>}</div>)}</div><div className="sectionTitle">Audit اخیر</div><div className="auditList">{(security.audit||[]).slice(0,50).map(x=><div key={x.id}><b>{x.event_type}</b><span>{dt(x.created_at)}</span><code>{JSON.stringify(x.metadata)}</code></div>)}</div></>}</div></div>}

function StepUpModal({onClose,onSuccess,notify}){const [password,setPassword]=useState("");const [busy,setBusy]=useState(false);const submit=async()=>{try{setBusy(true);await api("/api/v1/security/step-up/",{method:"POST",body:{password}});notify("تأیید امنیتی برای ۱۰ دقیقه فعال شد");if(onSuccess)await onSuccess();else onClose()}catch(e){notify(e.message)}finally{setBusy(false)}};return <Modal title="تأیید عملیات حساس" onClose={onClose}><div className="formGrid oneCol"><div className="securityNote"><KeyRound size={18}/><div><b>رمز عبور حساب CryptoSniper</b><span>برای حذف credential یا ارسال سفارش واقعی، تأیید مجدد لازم است.</span></div></div><div className="field"><label>رمز عبور</label><input autoFocus type="password" value={password} onChange={e=>setPassword(e.target.value)} onKeyDown={e=>e.key==="Enter"&&submit()}/></div><button className="primary fullBtn" disabled={busy} onClick={submit}>تأیید</button></div></Modal>}
function Modal({title,onClose,children}){return <div className="drawerMask" onClick={onClose}><div className="modal" onClick={e=>e.stopPropagation()}><div className="cardHead"><h3>{title}</h3><button className="iconBtn" onClick={onClose}><X size={18}/></button></div><div className="modalBody">{children}</div></div></div>}

createRoot(document.getElementById("root")).render(<App/>);
